277	+import { z } from "zod";
278	+import { formatIssues, type ValidationResult } from "../rules.js";
279	+
280	+/** World ticks per second (§15): the ledger's only clock. */
281	+export const WORLD_TICKS_PER_SECOND = 20;
282	+
283	+const ticks = z.int().nonnegative();
284	+
285	+/** The timings and amounts of §4, §11 and §12 the ledger enforces, in world ticks and gold. */
286	+export const objectiveRulesSchema = z.strictObject({
287	+  /** §4: hold interact this long, uninterrupted, at an unlocked source. */
288	+  collectTicks: z.int().positive(),
289	+  /** §12: one six-second interaction claims one rubbing from a recovery cache. */
290	+  cacheClaimTicks: z.int().positive(),
291	+  /** §4: the winner's theft choice window; without a choice the default applies. */
292	+  theftChoiceTicks: z.int().positive(),
293	+  /** §11: the PvP victory takes this percentage of the loser's gold, rounded down… */
294	+  pvpGoldPercent: z.int().min(0).max(100),
295	+  /** …capped at this much. */
296	+  pvpGoldCap: z.int().nonnegative(),
297	+  /** §11: a win over the same opponent within this long of the previous one pays no gold. */
298	+  repeatWinWindowTicks: ticks,
299	+  /** §11: every player's starting purse. */
300	+  startingGold: z.int().nonnegative(),
301	+  /** §12: a disconnected player's seat stays reserved this long. */
302	+  seatReservationTicks: z.int().positive(),
303	+});
304	+
305	+export type ObjectiveRules = z.infer<typeof objectiveRulesSchema>;
306	+
307	+export const objectiveRules = {
308	+  collectTicks: 6 * WORLD_TICKS_PER_SECOND,
309	+  cacheClaimTicks: 6 * WORLD_TICKS_PER_SECOND,
310	+  theftChoiceTicks: 5 * WORLD_TICKS_PER_SECOND,
311	+  pvpGoldPercent: 20,
312	+  pvpGoldCap: 50,
313	+  repeatWinWindowTicks: 3 * 60 * WORLD_TICKS_PER_SECOND,
314	+  startingGold: 50,
315	+  seatReservationTicks: 60 * WORLD_TICKS_PER_SECOND,
316	+} as const satisfies ObjectiveRules;
317	+
318	+export function validateObjectiveRules(candidate: unknown): ValidationResult<ObjectiveRules> {
319	+  const parsed = objectiveRulesSchema.safeParse(candidate);
320	+  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
321	+}
322	+
323	+/**
324	+ * §11's PvP gold: `pvpGoldPercent` of the loser's gold, rounded down, capped at `pvpGoldCap` and never more than the
325	+ * loser has, so a balance never goes negative. Gold is transferred, never minted.
326	+ */
327	+export function pvpGoldTransfer(rules: ObjectiveRules, loserGold: number): number {
328	+  if (!Number.isSafeInteger(loserGold) || loserGold <= 0) return 0;
329	+  const share = Math.floor((loserGold * rules.pvpGoldPercent) / 100);
330	+  return Math.min(share, rules.pvpGoldCap, loserGold);
331	+}
332	diff --git a/packages/content/src/objectives/sources.ts b/packages/content/src/objectives/sources.ts
333	new file mode 100644
334	index 0000000..c82b48e
335	--- /dev/null
336	+++ b/packages/content/src/objectives/sources.ts
337	@@ -0,0 +1,117 @@
338	+import { z } from "zod";
339	+import { formatIssues, rulesPresets, type RulesPreset, type ValidationResult } from "../rules.js";
340	+import { presetRubbings, rubbingIdSchema, rubbingTypeOf, rubbingTypeSchema } from "./types.js";
341	+
342	+/**
343	+ * Where a source can stand: an island index of the preset and an integer sub-unit position that the caller takes from
344	+ * the map. The ledger does not know the map; it only keeps the positions with the sources.
345	+ */
346	+export const sourceSiteSchema = z.strictObject({
347	+  island: z.int().nonnegative(),
348	+  x: z.int(),
349	+  y: z.int(),
350	+});
351	+
352	+export type SourceSite = z.infer<typeof sourceSiteSchema>;
353	+
354	+/** A source's id names its island and its place among that island's sources: `source-<island>-<slot>`. */
355	+export function sourceId(island: number, slot: number): string {
356	+  return `source-${island}-${slot}`;
357	+}
358	+
359	+export const assignedSourceSchema = z.strictObject({
360	+  id: z.string().regex(/^source-[0-9]+-[0-9]+$/, "a source id is source-<island>-<slot>"),
361	+  island: z.int().nonnegative(),
362	+  x: z.int(),
363	+  y: z.int(),
364	+  type: rubbingTypeSchema,
365	+  /** The rubbing sealed here at the start of the match. */
366	+  rubbingId: rubbingIdSchema,
367	+});
368	+
369	+export type AssignedSource = z.infer<typeof assignedSourceSchema>;
370	+
371	+interface Issue {
372	+  readonly path: (string | number)[];
373	+  readonly message: string;
374	+}
375	+
376	+/** The island rule shared by sites and assignments: `sourcesPerIsland` sources on each island, and no other island. */
377	+function islandIssues(preset: RulesPreset, islands: readonly number[]): Issue[] {
378	+  const issues: Issue[] = [];
379	+  if (islands.length !== preset.rubbings) {
380	+    issues.push({ path: [], message: `preset ${preset.id} needs ${preset.rubbings} sources, got ${islands.length}` });
381	+  }
382	+  const perIsland = new Map<number, number>();
383	+  islands.forEach((island, index) => {
384	+    if (island >= preset.islands) {
385	+      issues.push({ path: [index, "island"], message: `preset ${preset.id} has islands 0–${preset.islands - 1}` });
386	+    }
387	+    perIsland.set(island, (perIsland.get(island) ?? 0) + 1);
388	+  });
389	+  for (let island = 0; island < preset.islands; island++) {
390	+    const count = perIsland.get(island) ?? 0;
391	+    if (count !== preset.sourcesPerIsland) {
392	+      issues.push({ path: [], message: `island ${island} needs ${preset.sourcesPerIsland} source(s), got ${count}` });
393	+    }
394	+  }
395	+  return issues;
396	+}
397	+
398	+/** The sites the server offers for a preset: exactly `sourcesPerIsland` on each of its islands. */
399	+export function sourceSitesSchema(preset: RulesPreset) {
400	+  return z.array(sourceSiteSchema).superRefine((sites, ctx) => {
401	+    for (const issue of islandIssues(preset, sites.map((site) => site.island))) ctx.addIssue({ code: "custom", ...issue });
402	+  });
403	+}
404	+
405	+export function validateSourceSites(preset: RulesPreset, candidate: unknown): ValidationResult<SourceSite[]> {
406	+  const parsed = sourceSitesSchema(preset).safeParse(candidate);
407	+  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
408	+}
409	+
410	+/**
411	+ * The server-controlled assignment of rubbings to sources (§4): the preset's rubbings, each sealed at exactly one
412	+ * source, `sourcesPerIsland` sources on each island, every source id unique and naming its island.
413	+ */
414	+export const sourceAssignmentSchema = z
415	+  .strictObject({
416	+    preset: z.enum(["slice", "alpha"]),
417	+    /** The seed the assignment was drawn from, so it can be reproduced. */
418	+    seed: z.int().nonnegative(),
