429	+      if (ids.has(source.id)) ctx.addIssue({ code: "custom", path: ["sources", index, "id"], message: `duplicate source id ${source.id}` });
430	+      ids.add(source.id);
431	+      if (!source.id.startsWith(`source-${source.island}-`)) {
432	+        ctx.addIssue({ code: "custom", path: ["sources", index, "id"], message: `source ${source.id} is not on island ${source.island}` });
433	+      }
434	+      if (rubbingTypeOf(source.rubbingId) !== source.type) {
435	+        ctx.addIssue({ code: "custom", path: ["sources", index, "type"], message: `rubbing ${source.rubbingId} is not of type ${source.type}` });
436	+      }
437	+    });
438	+    const expected = presetRubbings(preset).map((rubbing) => rubbing.id).sort();
439	+    const actual = sources.map((source) => source.rubbingId).sort();
440	+    if (expected.join(",") !== actual.join(",")) {
441	+      ctx.addIssue({
442	+        code: "custom",
443	+        path: ["sources"],
444	+        message: `preset ${preset.id} seals each of ${expected.join(", ")} exactly once; got ${actual.join(", ")}`,
445	+      });
446	+    }
447	+  });
