461	+import { z } from "zod";
462	+import type { RulesPreset } from "../rules.js";
463	+
464	+/**
465	+ * The four rubbing types of §4, in the fixed type order that breaks ties when a theft defaults. A preset with fewer
466	+ * types (the slice's two) uses the first ones of this order.
467	+ */
468	+export const RUBBING_TYPES = ["sun", "moon", "tide", "storm"] as const;
469	+
470	+export const rubbingTypeSchema = z.enum(RUBBING_TYPES);
471	+export type RubbingType = z.infer<typeof rubbingTypeSchema>;
472	+
473	+/** A rubbing's stable id: its type and its copy number from 1, such as `tide-2`. It never changes (§4). */
474	+export const rubbingIdSchema = z.string().regex(/^(sun|moon|tide|storm)-[1-9][0-9]*$/, "a rubbing id is <type>-<copy>");
475	+
476	+/** The position of a type in the fixed type order. */
477	+export function rubbingTypeOrder(type: RubbingType): number {
478	+  return RUBBING_TYPES.indexOf(type);
479	+}
480	+
481	+export function rubbingId(type: RubbingType, copy: number): string {
482	+  if (!Number.isInteger(copy) || copy < 1) throw new RangeError(`a rubbing copy number starts at 1, got ${copy}`);
483	+  return `${type}-${copy}`;
484	+}
485	+
486	+/** The type a rubbing id names, or null for a malformed id. */
487	+export function rubbingTypeOf(id: string): RubbingType | null {
488	+  if (!rubbingIdSchema.safeParse(id).success) return null;
489	+  return id.slice(0, id.indexOf("-")) as RubbingType;
490	+}
491	+
492	+/** The types a preset plays with, in the fixed type order. */
493	+export function presetRubbingTypes(preset: RulesPreset): RubbingType[] {
494	+  if (preset.rubbingTypes > RUBBING_TYPES.length) {
495	+    throw new RangeError(`preset ${preset.id} asks for ${preset.rubbingTypes} rubbing types; there are ${RUBBING_TYPES.length}`);
496	+  }
497	+  return RUBBING_TYPES.slice(0, preset.rubbingTypes);
498	+}
499	+
500	+export interface RubbingDefinition {
501	+  readonly id: string;
502	+  readonly type: RubbingType;
503	+}
504	+
505	+/** Every rubbing of a preset, by type order then copy: `sun-1`, `sun-2`, … (slice: 2 × 4; alpha: 4 × 3). */
506	+export function presetRubbings(preset: RulesPreset): RubbingDefinition[] {
507	+  const copies = preset.rubbings / preset.rubbingTypes;
508	+  if (!Number.isInteger(copies)) throw new RangeError(`preset ${preset.id}: rubbings must split evenly across types`);
509	+  return presetRubbingTypes(preset).flatMap((type) =>
510	+    Array.from({ length: copies }, (_, index) => ({ id: rubbingId(type, index + 1), type })),
511	+  );
512	+}
