534	@@ -0,0 +1,184 @@
535	+import {
536	+  atTick,
537	+  moveRubbings,
538	+  noEffects,
539	+  playerRejection,
540	+  tickRejection,
541	+  updatePlayer,
542	+  type LedgerRejection,
543	+  type LedgerStep,
544	+  type Transfer,
545	+} from "./internal.js";
546	+import {
547	+  activeDuelOf,
548	+  findCache,
549	+  findPlayer,
550	+  findRubbing,
551	+  findSource,
552	+  heldTypes,
553	+  type LedgerChannel,
554	+  type LedgerState,
555	+} from "./state.js";
556	+
557	+/**
558	+ * - `started`: a new channel, at 0 held ticks.
559	+ * - `held`: one more tick held.
560	+ * - `reset`: the hold was interrupted (a tick without progress), so it counts from 0 again at this tick.
561	+ * - `collected` / `claimed`: the channel completed and the rubbing is the player's.
562	+ * - `failed`: the channel completed but its rubbing had gone or was no longer allowed (see `failure`); nothing moved.
563	+ * - `cancelled`: the channel was dropped.
564	+ */
565	+export type ChannelStatus = "started" | "held" | "reset" | "collected" | "claimed" | "failed" | "cancelled";
566	+
567	+export interface ChannelResult {
568	+  readonly ok: boolean;
569	+  readonly rejection: LedgerRejection | null;
570	+  readonly status: ChannelStatus | null;
571	+  /** Why a completed channel failed. */
572	+  readonly failure: LedgerRejection | null;
573	+  /** The player's channel as it now stands. */
574	+  readonly channel: LedgerChannel | null;
575	+  /** The rubbing collected or claimed. */
576	+  readonly rubbingId: string | null;
577	+  readonly transfers: readonly Transfer[];
578	+}
579	+
580	+function rejected(state: LedgerState, rejection: LedgerRejection, playerId: unknown): LedgerStep<ChannelResult> {
581	+  const channel = typeof playerId === "string" ? (findPlayer(state, playerId)?.channel ?? null) : null;
582	+  return { state, result: { ok: false, rejection, status: null, failure: null, channel, rubbingId: null, transfers: [] } };
583	+}
584	+
585	+function result(
586	+  state: LedgerState,
587	+  playerId: string,
588	+  status: ChannelStatus,
589	+  extra: { failure?: LedgerRejection; rubbingId?: string; transfers?: Transfer[] } = {},
590	+): LedgerStep<ChannelResult> {
591	+  return {
592	+    state,
593	+    result: {
594	+      ok: true,
595	+      rejection: null,
596	+      status,
597	+      failure: extra.failure ?? null,
598	+      channel: findPlayer(state, playerId)?.channel ?? null,
599	+      rubbingId: extra.rubbingId ?? null,
600	+      transfers: extra.transfers ?? [],
601	+    },
602	+  };
603	+}
604	+
605	+/** Why a player cannot start or keep a channel: they must be in the match, connected and out of any duel. */
606	+function actorRejection(state: LedgerState, playerId: unknown): LedgerRejection | null {
607	+  const refusal = playerRejection(state, playerId);
608	+  if (refusal) return refusal;
609	+  const id = playerId as string;
610	+  if (findPlayer(state, id)!.status === "disconnected") return "player-disconnected";
611	+  return activeDuelOf(state, id) ? "player-in-duel" : null;
612	+}
613	+
614	+/** Why the channel's rubbing cannot go to the player now, if it cannot. Checked at the start and again at the end. */
615	+function targetRejection(state: LedgerState, playerId: string, channel: LedgerChannel): LedgerRejection | null {
616	+  const rubbing = findRubbing(state, channel.rubbingId);
617	+  if (channel.kind === "collect") {
618	+    const source = findSource(state, channel.sourceId);
619	+    if (!source) return "unknown-source";
620	+    if (!source.unlocked) return "source-locked";
621	+    if (rubbing?.location.kind !== "source" || rubbing.location.sourceId !== source.id) return "source-empty";
622	+  } else {
623	+    if (!findCache(state, channel.cacheId)) return "unknown-cache";
624	+    if (rubbing?.location.kind !== "cache" || rubbing.location.cacheId !== channel.cacheId) return "not-in-cache";
625	+  }
626	+  return heldTypes(state, playerId).includes(rubbing.type) ? "type-held" : null;
627	+}
628	+
629	+function sameTarget(a: LedgerChannel | null, b: LedgerChannel): boolean {
630	+  if (a === null || a.kind !== b.kind || a.rubbingId !== b.rubbingId) return false;
631	+  return a.kind === "collect" ? b.kind === "collect" && a.sourceId === b.sourceId : b.kind === "claim" && a.cacheId === b.cacheId;
632	+}
633	+
634	+function start(state: LedgerState, playerId: string, channel: LedgerChannel, tick: number): LedgerStep<ChannelResult> {
635	+  const bad = tickRejection(state, tick) ?? actorRejection(state, playerId) ?? targetRejection(state, playerId, channel);
636	+  if (bad) return rejected(state, bad, playerId);
637	+  if (sameTarget(findPlayer(state, playerId)!.channel, channel)) return rejected(state, "duplicate", playerId);
638	+  return result(updatePlayer(atTick(state, tick), playerId, (player) => ({ ...player, channel })), playerId, "started");
639	+}
640	+
641	+export interface StartCollectRequest {
642	+  readonly playerId: string;
643	+  readonly sourceId: string;
644	+  readonly tick: number;
645	+}
646	+
647	+/**
648	+ * §4: starts holding interact at an unlocked source with its rubbing still sealed there, for a type the player does
649	+ * not hold. Starting replaces any other channel of the player; repeating the same start changes nothing.
650	+ */
651	+export function startCollect(state: LedgerState, request: StartCollectRequest): LedgerStep<ChannelResult> {
652	+  const { playerId, sourceId, tick } = request;
653	+  const source = typeof sourceId === "string" ? findSource(state, sourceId) : undefined;
654	+  if (!source) return rejected(state, tickRejection(state, tick) ?? "unknown-source", playerId);
655	+  return start(state, playerId, { kind: "collect", sourceId, rubbingId: source.rubbingId, startTick: tick, lastTick: tick, heldTicks: 0 }, tick);
656	+}
657	+
658	+export interface StartCacheClaimRequest {
659	+  readonly playerId: string;
660	+  readonly cacheId: string;
661	+  /** §12: one selected rubbing per interaction. */
662	+  readonly rubbingId: string;
663	+  readonly tick: number;
664	+}
665	+
666	+/** §12: starts the interaction that claims one selected rubbing from a cache, for a player missing its type. */
667	+export function startCacheClaim(state: LedgerState, request: StartCacheClaimRequest): LedgerStep<ChannelResult> {
668	+  const { playerId, cacheId, rubbingId, tick } = request;
669	+  if (typeof cacheId !== "string" || typeof rubbingId !== "string") return rejected(state, "invalid-request", playerId);
670	+  return start(state, playerId, { kind: "claim", cacheId, rubbingId, startTick: tick, lastTick: tick, heldTicks: 0 }, tick);
671	+}
672	+
673	+export interface ChannelTickRequest {
674	+  readonly playerId: string;
675	+  readonly tick: number;
676	+}
677	+
678	+/**
679	+ * The player held interact during `tick`. It must be the tick right after the channel's last one; after a gap the
680	+ * hold was interrupted and counts from 0 again. On reaching the rule's ticks the channel completes: the target is
681	+ * checked again, so of two players claiming the same rubbing only the first to complete gets it.
682	+ */
683	+export function progressChannel(state: LedgerState, request: ChannelTickRequest): LedgerStep<ChannelResult> {
684	+  const { playerId, tick } = request;
685	+  const bad = tickRejection(state, tick) ?? actorRejection(state, playerId);
686	+  if (bad) return rejected(state, bad, playerId);
687	+  const channel = findPlayer(state, playerId)!.channel;
688	+  if (channel === null) return rejected(state, "no-channel", playerId);
689	+  if (tick <= channel.lastTick) return rejected(state, "duplicate", playerId);
690	+  const now = atTick(state, tick);
691	+  if (tick > channel.lastTick + 1) {
692	+    const restarted = { ...channel, startTick: tick, lastTick: tick, heldTicks: 0 };
693	+    return result(updatePlayer(now, playerId, (player) => ({ ...player, channel: restarted })), playerId, "reset");
694	+  }
695	+  const held = { ...channel, lastTick: tick, heldTicks: channel.heldTicks + 1 };
696	+  const required = channel.kind === "collect" ? state.rules.collectTicks : state.rules.cacheClaimTicks;
697	+  if (held.heldTicks < required) {
698	+    return result(updatePlayer(now, playerId, (player) => ({ ...player, channel: held })), playerId, "held");
699	+  }
700	+  const done = updatePlayer(now, playerId, (player) => ({ ...player, channel: null }));
701	+  const failure = targetRejection(done, playerId, channel);
702	+  if (failure) return result(done, playerId, "failed", { failure });
703	+  const effects = noEffects();
704	+  const next = moveRubbings(done, [{ rubbingId: channel.rubbingId, to: { kind: "player", playerId } }], effects);
705	+  return result(next, playerId, channel.kind === "collect" ? "collected" : "claimed", {
706	+    rubbingId: channel.rubbingId,
707	+    transfers: effects.transfers,
708	+  });
709	+}
710	+
711	+/** The player let go of interact, moved or was interrupted: the channel ends and its progress is lost. */
712	+export function cancelChannel(state: LedgerState, request: ChannelTickRequest): LedgerStep<ChannelResult> {
713	+  const { playerId, tick } = request;
714	+  const bad = tickRejection(state, tick) ?? playerRejection(state, playerId);
715	+  if (bad) return rejected(state, bad, playerId);
716	+  if (findPlayer(state, playerId)!.channel === null) return rejected(state, "no-channel", playerId);
717	+  return result(updatePlayer(atTick(state, tick), playerId, (player) => ({ ...player, channel: null })), playerId, "cancelled");
718	+}
