754	+export interface DuelResult {
755	+  readonly ok: boolean;
756	+  readonly rejection: LedgerRejection | null;
757	+  /** The duel as it now stands (its current result for a rejected request), or null for an unknown duel. */
758	+  readonly duel: LedgerDuel | null;
759	+  readonly transfers: readonly Transfer[];
760	+  readonly cacheIds: readonly string[];
761	+}
762	+
763	+function rejected(state: LedgerState, rejection: LedgerRejection, duelId: unknown): LedgerStep<DuelResult> {
764	+  const duel = typeof duelId === "string" ? (findDuel(state, duelId) ?? null) : null;
765	+  return { state, result: { ok: false, rejection, duel, transfers: [], cacheIds: [] } };
766	+}
767	+
768	+function applied(state: LedgerState, duelId: string, effects: Effects): LedgerStep<DuelResult> {
769	+  return {
770	+    state,
771	+    result: { ok: true, rejection: null, duel: findDuel(state, duelId) ?? null, ...effects },
772	+  };
773	+}
774	+
775	+function replaceDuel(state: LedgerState, duel: LedgerDuel): LedgerState {
776	+  return { ...state, duels: state.duels.map((existing) => (existing.id === duel.id ? duel : existing)) };
777	+}
778	+
779	+export interface ReserveDuelRequest {
780	+  /** Created by the server for the encounter. */
781	+  readonly duelId: string;
782	+  readonly players: readonly [string, string];
783	+  readonly tick: number;
784	+}
785	+
786	+/**
787	+ * Reserves both players' rubbings inside the duel (§4, §16), so none of them can be collected, stolen or abandoned
788	+ * twice while it runs, and cancels both players' channels. A disconnected player can be challenged (§12).
789	+ */
790	+export function reserveDuel(state: LedgerState, request: ReserveDuelRequest): LedgerStep<DuelResult> {
791	+  const { duelId, players, tick } = request;
792	+  const bad = tickRejection(state, tick);
793	+  if (bad) return rejected(state, bad, duelId);
794	+  if (!isPlayerId(duelId) || !Array.isArray(players) || players.length !== 2) return rejected(state, "invalid-request", duelId);
795	+  if (findDuel(state, duelId)) return rejected(state, "duplicate", duelId);
796	+  const [a, b] = players;
797	+  if (a === b) return rejected(state, "same-player", duelId);
798	+  for (const playerId of players) {
799	+    const refusal = playerRejection(state, playerId) ?? (activeDuelOf(state, playerId) ? "player-in-duel" : null);
800	+    if (refusal) return rejected(state, refusal, duelId);
801	+  }
802	+  const effects = noEffects();
803	+  const duel: LedgerDuel = {
804	+    id: duelId,
805	+    players: [a, b],
806	+    startTick: tick,
807	+    phase: "fighting",
808	+    result: null,
809	+    choiceDeadline: null,
810	+    settlement: null,
811	+  };
812	+  let next: LedgerState = { ...atTick(state, tick), duels: [...state.duels, duel] };
813	+  for (const playerId of players) next = updatePlayer(next, playerId, (player) => ({ ...player, channel: null }));
814	+  next = moveRubbings(
815	+    next,
816	+    next.rubbings.flatMap((rubbing) =>
817	+      rubbing.location.kind === "player" && players.includes(rubbing.location.playerId)
818	+        ? [{ rubbingId: rubbing.id, to: { kind: "duel", duelId, playerId: rubbing.location.playerId } as const }]
819	+        : [],
820	+    ),
821	+    effects,
822	+  );
823	+  return applied(next, duelId, effects);
824	+}
825	+
826	+export interface ReportDuelResultRequest {
827	+  readonly duelId: string;
828	+  readonly tick: number;
829	+  /** `cancelled`: both players forfeited on the same tick (§12), which settles like a draw. */
830	+  readonly outcome: "win" | "draw" | "cancelled";
831	+  /** The winner, for `win` only. */
832	+  readonly winner?: string;
833	+}
834	+
835	+/**
836	+ * Records the fight's result once. A draw or cancellation settles at once with nothing moving. A win opens the
837	+ * winner's theft choice window, or settles at once (gold only) when no type is eligible. Any later result message
838	+ * for the duel, even a different one, changes nothing and returns the current result.
839	+ */
840	+export function reportDuelResult(state: LedgerState, request: ReportDuelResultRequest): LedgerStep<DuelResult> {
841	+  const { duelId, tick, outcome, winner } = request;
842	+  const bad = tickRejection(state, tick);
843	+  if (bad) return rejected(state, bad, duelId);
844	+  const duel = typeof duelId === "string" ? findDuel(state, duelId) : undefined;
845	+  if (!duel) return rejected(state, "unknown-duel", duelId);
846	+  if (duel.phase !== "fighting") return rejected(state, "already-resolved", duelId);
847	+  if (outcome === "win") {
848	+    if (winner === undefined || !duel.players.includes(winner)) return rejected(state, "not-a-participant", duelId);
849	+  } else if ((outcome !== "draw" && outcome !== "cancelled") || winner !== undefined) {
850	+    return rejected(state, "invalid-request", duelId);
851	+  }
852	+  const effects = noEffects();
853	+  const next = recordResult(atTick(state, tick), duel, outcome, winner ?? null, false, tick, effects);
854	+  return applied(next, duelId, effects);
855	+}
856	+
857	+/** Records a result for a duel still fighting; shared with a forfeit by a player who leaves. */
858	+export function recordResult(
859	+  state: LedgerState,
860	+  duel: LedgerDuel,
861	+  outcome: DuelResultRecord["outcome"],
862	+  winner: string | null,
863	+  forfeit: boolean,
864	+  tick: number,
865	+  effects: Effects,
866	+): LedgerState {
867	+  if (outcome !== "win") {
868	+    const result: DuelResultRecord = { outcome, winner: null, loser: null, forfeit: false, tick };
869	+    const settlement: DuelSettlement = {
870	+      tick,
871	+      stolenRubbingId: null,
872	+      stolenType: null,
873	+      choice: "none",
874	+      gold: 0,
875	+      goldSuppressed: false,
876	+    };
877	+    let next = replaceDuel(state, { ...duel, phase: "settled", result, settlement });
878	+    for (const playerId of duel.players) {
879	+      next = releaseTo(next, playerId, reservedIn(next, duel.id, playerId).map((rubbing) => rubbing.id), tick, effects);
880	+    }
881	+    return next;
882	+  }
883	+  const loser = duel.players[0] === winner ? duel.players[1] : duel.players[0];
884	+  const decided: LedgerDuel = { ...duel, result: { outcome, winner, loser, forfeit, tick } };
885	+  const next = replaceDuel(state, decided);
886	+  if (eligibleTheftTypes(next, duel.id).length === 0) return commitWin(next, decided, tick, null, effects);
887	+  return replaceDuel(next, { ...decided, phase: "choosing", choiceDeadline: tick + state.rules.theftChoiceTicks });
888	+}
889	+
890	+/**
891	+ * Commits a decided duel, once: validates eligibility again, moves the stolen rubbing (the winner's valid choice, or
892	+ * the default), transfers gold unless suppressed, grants the loser a fresh rumor for the lost type, and returns every
893	+ * other reserved rubbing to its owner (or to a cache where its owner left). A winner who has left takes nothing.
894	+ */
895	+export function commitWin(
896	+  state: LedgerState,
897	+  duel: LedgerDuel,
898	+  tick: number,
899	+  choice: RubbingType | null,
900	+  effects: Effects,
901	+): LedgerState {
902	+  const result = duel.result;
903	+  if (duel.phase === "settled" || result?.outcome !== "win" || result.winner === null || result.loser === null) {
904	+    throw new Error(`duel ${duel.id} has no win to commit`);
905	+  }
906	+  const { winner, loser } = result;
907	+  const winnerPlayer = findPlayer(state, winner);
908	+  const loserPlayer = findPlayer(state, loser);
909	+  if (!winnerPlayer || !loserPlayer) throw new Error(`duel ${duel.id} names an unknown player`);
910	+  const winnerPresent = winnerPlayer.status !== "left";
911	+
912	+  const eligible = eligibleTheftTypes(state, duel.id);
913	+  const chosen = choice !== null && eligible.includes(choice) ? choice : null;
914	+  const stolenType = chosen ?? defaultTheftType(state, eligible);
915	+  const stolen = stolenType === null ? undefined : reservedIn(state, duel.id, loser).find((rubbing) => rubbing.type === stolenType);
916	+
917	+  const previous = state.wins.find((win) => win.winner === winner && win.loser === loser);
918	+  const goldSuppressed =
919	+    winnerPresent && previous !== undefined && result.tick - previous.tick < state.rules.repeatWinWindowTicks;
920	+  const gold = winnerPresent && !goldSuppressed ? pvpGoldTransfer(state.rules, loserPlayer.gold) : 0;
921	+
922	+  const settlement: DuelSettlement = {
923	+    tick,
924	+    stolenRubbingId: stolen?.id ?? null,
925	+    stolenType: stolen ? stolen.type : null,
926	+    choice: stolen === undefined ? "none" : chosen !== null ? "winner" : "default",
927	+    gold,
928	+    goldSuppressed,
929	+  };
930	+  let next = replaceDuel(state, { ...duel, phase: "settled", settlement });
931	+  if (stolen) {
932	+    next = moveRubbings(next, [{ rubbingId: stolen.id, to: { kind: "player", playerId: winner } }], effects);
933	+    const lost = stolen.type;
934	+    next = updatePlayer(next, loser, (player) => ({
935	+      ...player,
936	+      freshRumors: player.freshRumors.includes(lost) ? player.freshRumors : [...player.freshRumors, lost].sort(byTypeOrder),
937	+    }));
938	+  }
939	+  if (gold > 0) {
940	+    next = updatePlayer(next, loser, (player) => ({ ...player, gold: player.gold - gold }));
941	+    next = updatePlayer(next, winner, (player) => ({ ...player, gold: player.gold + gold }));
942	+  }
943	+  if (winnerPresent) {
944	+    const record = { winner, loser, tick: result.tick };
945	+    next = {
946	+      ...next,
947	+      wins: previous ? next.wins.map((win) => (win === previous ? record : win)) : [...next.wins, record],
948	+    };
949	+  }
950	+  for (const playerId of [winner, loser]) {
951	+    next = releaseTo(next, playerId, reservedIn(next, duel.id, playerId).map((rubbing) => rubbing.id), tick, effects);
952	+  }
953	+  return next;
954	+}
955	+
956	+export interface ChooseTheftRequest {
957	+  /** The server-created duel result the choice refers to (§16). */
958	+  readonly duelId: string;
959	+  readonly playerId: string;
960	+  readonly type: RubbingType;
961	+  readonly tick: number;
962	+}
963	+
964	+/** The winner's theft choice, before the deadline and for an eligible type; it commits the settlement at once. */
965	+export function chooseTheft(state: LedgerState, request: ChooseTheftRequest): LedgerStep<DuelResult> {
966	+  const { duelId, playerId, type, tick } = request;
967	+  const bad = tickRejection(state, tick);
968	+  if (bad) return rejected(state, bad, duelId);
969	+  const duel = typeof duelId === "string" ? findDuel(state, duelId) : undefined;
970	+  if (!duel) return rejected(state, "unknown-duel", duelId);
971	+  if (duel.phase === "settled") return rejected(state, "already-resolved", duelId);
972	+  if (duel.phase !== "choosing" || duel.result === null || duel.choiceDeadline === null) {
973	+    return rejected(state, "not-choosing", duelId);
974	+  }
975	+  if (playerId !== duel.result.winner) return rejected(state, "not-winner", duelId);
976	+  if (tick >= duel.choiceDeadline) return rejected(state, "choice-window-closed", duelId);
977	+  if (!rubbingTypeSchema.safeParse(type).success || !eligibleTheftTypes(state, duelId).includes(type)) {
978	+    return rejected(state, "ineligible-type", duelId);
979	+  }
980	+  const effects = noEffects();
981	+  const next = commitWin(atTick(state, tick), duel, tick, type, effects);
982	+  return applied(next, duelId, effects);
983	+}
984	+
985	+export interface AdvanceRequest {
986	+  readonly tick: number;
987	+}
988	+
989	+export interface AdvanceResult {
990	+  readonly ok: boolean;
991	+  readonly rejection: LedgerRejection | null;
992	+  /** Duels whose choice window closed at this tick, settled with the default theft. */
993	+  readonly settled: readonly LedgerDuel[];
994	+  readonly transfers: readonly Transfer[];
995	+  readonly cacheIds: readonly string[];
996	+}
997	+
998	+/**
999	+ * Moves the ledger's clock to `tick` and settles every duel whose choice window has closed with the default theft,
1000	+ * in reservation order. Call it once per world tick before that tick's requests.
1001	+ */
1002	+export function advanceLedger(state: LedgerState, request: AdvanceRequest): LedgerStep<AdvanceResult> {
1003	+  const bad = tickRejection(state, request.tick);
1004	+  if (bad) return { state, result: { ok: false, rejection: bad, settled: [], transfers: [], cacheIds: [] } };
1005	+  const { tick } = request;
1006	+  const effects = noEffects();
1007	+  let next = atTick(state, tick);
1008	+  const settled: string[] = [];
1009	+  for (const duel of state.duels) {
1010	+    if (duel.phase === "choosing" && duel.choiceDeadline !== null && tick >= duel.choiceDeadline) {
1011	+      next = commitWin(next, findDuel(next, duel.id)!, tick, null, effects);
1012	+      settled.push(duel.id);
1013	+    }
1014	+  }
1015	+  return {
1016	+    state: next,
1017	+    result: { ok: true, rejection: null, settled: settled.map((id) => findDuel(next, id)!), ...effects },
1018	+  };
1019	+}
