2702	+/**
2703	+ * Deals the preset's rubbings onto the sites with the seeded generator: a Fisher–Yates shuffle, so the server alone
2704	+ * decides, and the same seed and sites always give the same assignment. Source ids number each island's sites in the
2705	+ * order given.
2706	+ */
2707	+export function assignSources(
2708	+  presetId: RulesPresetId,
2709	+  sites: readonly SourceSite[],
2710	+  seed: number,
2711	+): { assignment: SourceAssignment; rng: number } {
2712	+  if (!Number.isInteger(seed)) throw new RangeError(`seed must be an integer, got ${seed}`);
2713	+  const preset = rulesPresets[presetId];
2714	+  const checked = validateSourceSites(preset, sites);
2715	+  if (!checked.ok) throw new Error(`invalid source sites for ${presetId}: ${checked.issues.join("; ")}`);
2716	+  const deck = presetRubbings(preset);
2717	+  let rng = seed >>> 0;
2718	+  for (let index = deck.length - 1; index > 0; index--) {
2719	+    const drawn = nextInt(rng, index + 1);
2720	+    rng = drawn.state;
2721	+    [deck[index], deck[drawn.value]] = [deck[drawn.value]!, deck[index]!];
2722	+  }
2723	+  const slots = new Map<number, number>();
2724	+  const sources = checked.value.map((site, index) => {
2725	+    const slot = slots.get(site.island) ?? 0;
2726	+    slots.set(site.island, slot + 1);
2727	+    const rubbing = deck[index]!;
2728	+    return { id: sourceId(site.island, slot), island: site.island, x: site.x, y: site.y, type: rubbing.type, rubbingId: rubbing.id };
2729	+  });
2730	+  const assignment = validateSourceAssignment({ preset: presetId, seed: seed >>> 0, sources });
2731	+  if (!assignment.ok) throw new Error(`invalid source assignment: ${assignment.issues.join("; ")}`);
2732	+  return { assignment: assignment.value, rng };
