+import { rulesPresets, type RulesPresetId } from "@pirate-sea-race/content";
+import { describe, expect, it } from "vitest";
+import { nextInt } from "../random.js";
+import {
+  activeDuelOf,
+  addPlayer,
+  advanceLedger,
+  cacheRubbings,
+  cancelChannel,
+  checkLedger,
+  chooseTheft,
+  createLedger,
+  disconnectPlayer,
+  eligibleTheftTypes,
+  expireReservation,
+  findPlayer,
+  findRubbing,
+  hashState,
+  heldTypes,
+  progressChannel,
+  quitPlayer,
+  reconnectPlayer,
